/// Complete initial state required by the mail workspace.
class WorkspaceSnapshot {
  final List<MailboxDto> mailboxes;
  final List<String> favoriteMailboxIds;

  /// Mailboxes whose folder subtree is collapsed in the folder pane.
  final List<String> collapsedMailboxIds;
  final bool darkModeEnabled;
  final List<MessageDto> messages;
  final List<CalendarEventDto> calendarEvents;
  final List<TaskDto> tasks;
  final List<ContactDto> contacts;
  final List<MailAccountDto> mailAccounts;
  final List<String> syncWarnings;

  /// Compact IMAP catalogue entries still scheduled for automatic
  /// continuation after the current synchronization pass.
  final int catalogMessagesRemaining;
  final int deltaMailboxesSynchronized;
  final int fullMailboxesReconciled;
  final int qresyncMailboxesSynchronized;
  final int pendingMailOperations;

  const WorkspaceSnapshot({
    required this.mailboxes,
    required this.favoriteMailboxIds,
    required this.collapsedMailboxIds,
    required this.darkModeEnabled,
    required this.messages,
