    required this.catalogMessagesRemaining,
    required this.deltaMailboxesSynchronized,
    required this.fullMailboxesReconciled,
    required this.qresyncMailboxesSynchronized,
    required this.pendingMailOperations,
  });

  @override
  int get hashCode =>
      mailboxes.hashCode ^
      favoriteMailboxIds.hashCode ^
      collapsedMailboxIds.hashCode ^
      darkModeEnabled.hashCode ^
      messages.hashCode ^
      calendarEvents.hashCode ^
      tasks.hashCode ^
      contacts.hashCode ^
      mailAccounts.hashCode ^
      syncWarnings.hashCode ^
      catalogMessagesRemaining.hashCode ^
      deltaMailboxesSynchronized.hashCode ^
      fullMailboxesReconciled.hashCode ^
      qresyncMailboxesSynchronized.hashCode ^
      pendingMailOperations.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WorkspaceSnapshot &&
          runtimeType == other.runtimeType &&
          mailboxes == other.mailboxes &&
          favoriteMailboxIds == other.favoriteMailboxIds &&
          collapsedMailboxIds == other.collapsedMailboxIds &&
          darkModeEnabled == other.darkModeEnabled &&
          messages == other.messages &&
          calendarEvents == other.calendarEvents &&
          tasks == other.tasks &&
          contacts == other.contacts &&
